fn fibonacci(n: usize) -> Vec<i32> {
    let mut ret = Vec::with_capacity(n);
    ret.push(0);
    ret.push(1);

    for i in 2..n {
        // Safe to unwrap because previous values exist and fit in i32
        let next = ret[i - 1] + ret[i - 2];
        ret.push(next);
    }

    ret
}